"""Portable business-profile matching; the Designer edits inputs.profiles."""
import unicodedata


def clean(value):
    return unicodedata.normalize('NFKC', str(value or '')).strip()


def main(inputs):
    projects = []
    seen = set()
    for profile in inputs['profiles']:
        if not profile['id'] or profile['id'] in seen:
            raise ValueError('业务方案标识为空或重复')
        seen.add(profile['id'])
        if not profile['enabled']:
            continue
        for project in inputs['snapshot']['projects']:
            number = clean(project.get('check_item_no'))
            method = clean(project.get('check_method'))
            # Codes are strings. In particular, 5103.05 is not 5103.5.
            matches = any(number == clean(rule['project_number']) and method == clean(rule['method'])
                          for rule in profile['matches'])
            if not matches:
                continue
            projects.append({
                'id': project['project_key'] + ':' + profile['id'], 'kind': 'option',
                'label': project['check_item_name'] + ' · ' + method + ' · ' + profile['name'],
                'fingerprint': project['project_key'],
                'metadata': {'project': project, 'profile': profile},
            })
    return {'projects': projects}

"""Copied verbatim into the workflow's editable Python node."""
import re
import unicodedata


def clean(value):
    return unicodedata.normalize('NFKC', str(value or '')).strip()


def main(inputs):
    if inputs['truncated']:
        raise ValueError('图片超过查询上限，请填写更具体的相对目录后重新查询')
    number = clean(inputs['inspection_number']).upper()
    pattern = r'(?<![A-Z0-9])' + re.escape(number) + r'(?![A-Z0-9])'
    items = []
    for source in inputs['items']:
        path = clean(source['relative_path']).replace('\\', '/')
        if not re.search(pattern, path.upper()):
            continue
        item = dict(source)
        item['kind'] = 'image'
        item['metadata'] = dict(source.get('metadata') or {})
        items.append(item)
    items.sort(key=lambda item: [int(part) if part.isdigit() else part.casefold()
                                for part in re.split(r'(\d+)', item['relative_path'])])
    if not items:
        raise ValueError('未找到匹配编号的图片，请核对图片目录和文件索引')
    projects = inputs['projects']
    if not projects:
        raise ValueError('任务没有符合项目与方法规则的检测项目')
    return {'inspection_number': number, 'items': items, 'projects': projects}

